/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy import ndimage as nd
A=np.load('source_pixels.npz')['rgb'];bg=np.median(A,axis=0)
for t in range(0,41,2):
 d=np.max(abs(A[t].astype(float)-bg),2)>35;l,n=nd.label(d); comps=[]
 for s in nd.find_objects(l):
  if s is None:continue
  yy,xx=s; area=d[s].sum()
  if area>18:comps.append((int(area),(xx.start,yy.start,xx.stop,yy.stop)))
 print(t,comps)
# colored ascii ROI at selected frames
for t in [0,2,4,6,8,10,12,16,24]:
 print('\\nFRAME',t)
 f=A[t];roi=f[0:98,106:146];
 for y in range(0,98,2):
  line=''
  for x in range(0,40,2):
   r,g,b=roi[y:y+2,x:x+2].mean((0,1)); v=(r+g+b)/3
   c='W' if min(r,g,b)>175 and max(r,g,b)-min(r,g,b)<40 else 'R' if r>g*1.4 and r>b*1.4 else 'B' if b>r*1.3 else 'Y' if r>b*1.4 and g>b*1.2 else ' .:-=+*#%@'[min(9,int(v/256*10))]
   line+=c
  print(line)
PY"
